    "url": "https://www.thenorthfacekorea.co.kr/event/view/eventCategoryNF/93338#faq",
    "name": "자주 묻는 질문",
    "inLanguage": "ko-KR",
    "isPartOf": {"@id": "https://www.thenorthfacekorea.co.kr/event/view/eventCategoryNF/93338#webpage"},
    "mainEntity": [

        {
            "@type": "Question",
            "name": "\uBC15\uBCF4\uAC80\u00B7\uAE40\uB098\uC601\u00B7\uC804\uC18C\uBBF8\u00B7\uC774\uD638\uC5F0\uC774 \uCC29\uC6A9\uD55C \uACA8\uC6B8 \uBC29\uD55C\uC6A9\uD488\uC740 \uC5B4\uB514\uC5D0\uC11C \uBCFC \uC218 \uC788\uB098\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uC774 \uAE30\uD68D\uC804\uC5D0\uC11C \uBC15\uBCF4\uAC80\u00B7\uAE40\uB098\uC601\u00B7\uC804\uC18C\uBBF8\u00B7\uC774\uD638\uC5F0\uC758 \uCC29\uC7A5\uACFC \uD568\uAED8 \uB178\uC2A4\uD398\uC774\uC2A4 \uACA8\uC6B8 \uBC29\uD55C\uC6A9\uD488\uC744 \uB9CC\uB098\uBCFC \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uBE44\uB2C8\uC640 \uBC29\uD55C \uBAA8\uC790, \uC7A5\uAC11 \uB4F1 \uD654\uBCF4\uC5D0 \uC5F0\uACB0\uB41C \uC0C1\uD488\uC5D0\uC11C \uB3D9\uC77C\uD55C \uCEEC\uB7EC\uC640 \uC0C1\uC138 \uC815\uBCF4\uB97C \uD655\uC778\uD574 \uC8FC\uC138\uC694."
            }
        },


        {
            "@type": "Question",
            "name": "\uACA8\uC6B8 \uBE44\uB2C8\uB294 \uC5B4\uB5A4 \uAE30\uC900\uC73C\uB85C \uACE0\uB974\uBA74 \uC88B\uC744\uAE4C\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uC18C\uC7AC\uC640 \uD54F, \uB514\uC790\uC778\uC744 \uAE30\uC900\uC73C\uB85C \uC0B4\uD3B4\uBCF4\uC138\uC694. \uD3EC\uADFC\uD55C \uC6B8\uACFC \uD50C\uB9AC\uC2A4 \uC18C\uC7AC\uBD80\uD130 \uBCA0\uC774\uC9C1\uD55C \uB2C8\uD2B8, \uB85C\uACE0\u00B7\uB808\uD130\uB9C1 \uB514\uC790\uC778\uAE4C\uC9C0 \uB2E4\uC591\uD558\uAC8C \uAD6C\uC131\uB418\uC5B4 \uC788\uC5B4 \uB370\uC77C\uB9AC \uC2A4\uD0C0\uC77C\uC774\uB098 \uC544\uC6C3\uB3C4\uC5B4 \uD65C\uB3D9\uC5D0 \uB9DE\uCDB0 \uC120\uD0DD\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4."
            }
        },


        {
            "@type": "Question",
            "name": "\uC774\uC5B4\uBA38\uD504 \uCEA1\uACFC \uC77C\uBC18 \uACA8\uC6B8 \uBAA8\uC790\uB294 \uC5B4\uB5BB\uAC8C \uB2E4\uB978\uAC00\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uC774\uC5B4\uBA38\uD504 \uCEA1\uC740 \uADC0\uB97C \uAC10\uC2F8\uB294 \uADC0\uB2EC\uC774 \uB514\uD14C\uC77C\uC744 \uC801\uC6A9\uD574 \uCD94\uC6B4 \uB0A0\uC528\uC5D0 \uBCF4\uC628\uC131\uC744 \uB192\uC778 \uBC29\uD55C \uBAA8\uC790\uC785\uB2C8\uB2E4. \uD50C\uB9AC\uC2A4\u00B7\uD328\uB529\u00B7\uB2E4\uC6B4 \uB4F1 \uC18C\uC7AC\uAC00 \uB2E4\uC591\uD558\uBA70, \uC77C\uBC18 \uCEA1\uC774\uB098 \uBC84\uD0B7\uD587 \uD615\uD0DC\uC758 \uBC29\uD55C \uBAA8\uC790\uB3C4 \uC788\uC73C\uBBC0\uB85C \uC6D0\uD558\uB294 \uCC29\uC6A9 \uBC29\uC2DD\uACFC \uB514\uC790\uC778\uC5D0 \uB9DE\uCDB0 \uBE44\uAD50\uD574 \uBCF4\uC138\uC694."
            }
        },


        {
            "@type": "Question",
            "name": "\uACA8\uC6B8 \uC7A5\uAC11\uC744 \uACE0\uB97C \uB54C \uC5B4\uB5A4 \uAE30\uB2A5\uC744 \uD655\uC778\uD558\uBA74 \uC88B\uC744\uAE4C\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uBCF4\uC628 \uC18C\uC7AC\uC640 \uCC29\uC6A9\uAC10, \uD65C\uB3D9\uC5D0 \uD544\uC694\uD55C \uAE30\uB2A5\uC744 \uD655\uC778\uD574 \uC8FC\uC138\uC694. \uD50C\uB9AC\uC2A4 \uC18C\uC7AC\uC758 \uC7A5\uAC11\uBD80\uD130 \uBC29\uD48D \uB514\uD14C\uC77C\uACFC \uC2A4\uB9C8\uD2B8 \uD130\uCE58 \uAE30\uB2A5\uC744 \uAC16\uCD98 \uC81C\uD488\uAE4C\uC9C0 \uC788\uC5B4 \uC77C\uC0C1\uC0DD\uD65C\uACFC \uC57C\uC678 \uD65C\uB3D9\uC5D0 \uB9DE\uCDB0 \uC120\uD0DD\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4."
            }
        },


        {
            "@type": "Question",
            "name": "\uBAA9\uB3C4\uB9AC\u00B7\uBAA9 \uC6CC\uBA38\u00B7\uBC14\uB77C\uD074\uB77C\uBC14\u00B7\uADC0\uB9C8\uAC1C\uB294 \uC5B4\uB5BB\uAC8C \uC120\uD0DD\uD558\uBA74 \uC88B\uC744\uAE4C\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uB530\uB73B\uD558\uAC8C \uBCF4\uD638\uD558\uACE0 \uC2F6\uC740 \uBD80\uC704\uC640 \uD65C\uB3D9 \uD658\uACBD\uC5D0 \uB530\uB77C \uC120\uD0DD\uD574 \uBCF4\uC138\uC694. \uBAA9\uC744 \uAC10\uC2F8\uB294 \uBA38\uD50C\uB7EC\uC640 \uBAA9 \uC6CC\uBA38(\uB125\uAC8C\uC774\uD130), \uADC0\uB97C \uBCF4\uD638\uD558\uB294 \uADC0\uB9C8\uAC1C, \uC5BC\uAD74\uACFC \uBAA9\uAE4C\uC9C0 \uD3ED\uB113\uAC8C \uAC10\uC2F8\uB294 \uBC14\uB77C\uD074\uB77C\uBC14 \uB4F1 \uCC29\uC6A9 \uBC94\uC704\uC640 \uD615\uD0DC\uAC00 \uC11C\uB85C \uB2E4\uB985\uB2C8\uB2E4"
            }
        },


        {
            "@type": "Question",
            "name": "\uACA8\uC6B8 \uBC29\uD55C\uC6A9\uD488\uC740 \uC5B4\uB5A4 \uAE30\uC900\uC73C\uB85C \uACE0\uB974\uBA74 \uC88B\uC744\uAE4C\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uD3C9\uC18C \uD65C\uB3D9\uACFC \uD544\uC694\uD55C \uBCF4\uC628 \uBD80\uC704\uB97C \uBA3C\uC800 \uD655\uC778\uD574 \uBCF4\uC138\uC694. \uC77C\uC0C1\uC5D0\uC11C\uB294 \uBE44\uB2C8\u00B7\uBA38\uD50C\uB7EC\u00B7\uADC0\uB9C8\uAC1C\uCC98\uB7FC \uAC04\uD3B8\uD55C \uC544\uC774\uD15C\uC744, \uACA8\uC6B8 \uC5EC\uD589\uC774\uB098 \uCEA0\uD551\u00B7\uC544\uC6C3\uB3C4\uC5B4\uC5D0\uC11C\uB294 \uC774\uC5B4\uBA38\uD504 \uCEA1\u00B7\uC7A5\uAC11\u00B7\uBAA9 \uC6CC\uBA38\u00B7\uBC14\uB77C\uD074\uB77C\uBC14 \uB4F1 \uBCF4\uC628 \uBC94\uC704\uAC00 \uB113\uC740 \uC544\uC774\uD15C\uC744 \uBE44\uAD50\uD574 \uC120\uD0DD\uD558\uB294 \uAC83\uC774 \uC88B\uC2B5\uB2C8\uB2E4."
            }
        }

    ]
}

{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "@id": "https://www.thenorthfacekorea.co.kr/event/view/eventCategoryNF/93344#faq",
    "url": "https://www.thenorthfacekorea.co.kr/event/view/eventCategoryNF/93344#faq",
    "name": "자주 묻는 질문",
    "inLanguage": "ko-KR",
    "isPartOf": {"@id": "https://www.thenorthfacekorea.co.kr/event/view/eventCategoryNF/93344#webpage"},
    "mainEntity": [

        {
            "@type": "Question",
            "name": "\uB178\uC2A4\uD398\uC774\uC2A4 \uBE14\uB799\uD504\uB77C\uC774\uB370\uC774 2026\uC740 \uC5B8\uC81C\uAE4C\uC9C0 \uC9C4\uD589\uB418\uB098\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uB178\uC2A4\uD398\uC774\uC2A4 \uBE14\uB799\uD504\uB77C\uC774\uB370\uC774 2026\uC740 2026\uB144 11\uC6D4 12\uC77C\uBD80\uD130 12\uC6D4 3\uC77C\uAE4C\uC9C0 \uC9C4\uD589\uB429\uB2C8\uB2E4. \uD589\uC0AC \uC77C\uC815\uACFC \uB0B4\uC6A9\uC740 \uC6B4\uC601 \uC0AC\uC815\uC5D0 \uB530\uB77C \uBCC0\uACBD\uB418\uAC70\uB098 \uC911\uB2E8\uB420 \uC218 \uC788\uC2B5\uB2C8\uB2E4."
            }
        },


        {
            "@type": "Question",
            "name": "\uBAA8\uB4E0 \uC0C1\uD488\uC774 30% \uD560\uC778\uB418\uB098\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uC544\uB2C8\uC694. \uC774\uBC88 \uAE30\uD68D\uC804\uC758 \uCD5C\uB300 \uD560\uC778\uC728\uC740 30%\uC774\uBA70, \uC77C\uBD80 \uC0C1\uD488\uC740 \uD504\uB85C\uBAA8\uC158 \uB300\uC0C1\uC5D0\uC11C \uC81C\uC678\uB429\uB2C8\uB2E4. \uC0C1\uD488\uBCC4 \uD560\uC778\uC728\uACFC \uD310\uB9E4 \uAC00\uACA9\uC740 \uAC01 \uC0C1\uD488 \uC0C1\uC138 \uD398\uC774\uC9C0\uC5D0\uC11C \uD655\uC778\uD574 \uC8FC\uC138\uC694."
            }
        },


        {
            "@type": "Question",
            "name": "\uC774\uBC88 \uBE14\uB799\uD504\uB77C\uC774\uB370\uC774 \uB300\uD45C \uC0C1\uD488\uC740 \uBB34\uC5C7\uC778\uAC00\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uB300\uD45C \uC0C1\uD488\uC740 \uB0A8\uC131 \uC368\uBC0B \uB9C8\uD14C\uD638\uB978 \uB2E4\uC6B4 \uC790\uCF13, \uC5EC\uC131 \uC5D8\uB77C \uB2E4\uC6B4 \uC790\uCF13, \uD0A4\uC988 \uD074\uB77C\uC774\uB4DC \uB2E4\uC6B4 \uC790\uCF13, \uBCF4\uB808\uC54C\uB9AC\uC2A4 \uBBF8\uB2C8 \uBC31\uD329, \uC2A4\uB178\uC6B0 \uBBAC\uC785\uB2C8\uB2E4. \uC0C9\uC0C1\uACFC \uC0AC\uC774\uC988\uBCC4 \uAD6C\uB9E4 \uAC00\uB2A5 \uC5EC\uBD80\uB294 \uC0C1\uD488 \uC0C1\uC138 \uD398\uC774\uC9C0\uC5D0\uC11C \uD655\uC778\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4."
            }
        },


        {
            "@type": "Question",
            "name": "\uD328\uB529 \uC678\uC5D0 \uC5B4\uB5A4 \uC0C1\uD488\uC744 \uC0B4\uD3B4\uBCFC \uC218 \uC788\uB098\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uB2E4\uC6B4\u00B7\uD328\uB529 \uC678\uC5D0\uB3C4 \uD50C\uB9AC\uC2A4, \uC790\uCF13, \uC6A9\uD488, \uC2E0\uBC1C, \uD0A4\uC988 \uCE74\uD14C\uACE0\uB9AC\uC758 \uD589\uC0AC \uC0C1\uD488\uC744 \uC0B4\uD3B4\uBCFC \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uCE74\uD14C\uACE0\uB9AC \uB0B4 \uC0C1\uD488\uBCC4 \uD589\uC0AC \uC801\uC6A9 \uC5EC\uBD80\uB294 \uB2E4\uB97C \uC218 \uC788\uC2B5\uB2C8\uB2E4."
            }
        }

    ]
}

{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "@id": "https://www.thenorthfacekorea.co.kr/event/view/eventCategoryNF/93343#faq",
    "url": "https://www.thenorthfacekorea.co.kr/event/view/eventCategoryNF/93343#faq",
    "name": "자주 묻는 질문",
    "inLanguage": "ko-KR",
    "isPartOf": {"@id": "https://www.thenorthfacekorea.co.kr/event/view/eventCategoryNF/93343#webpage"},
    "mainEntity": [

        {
            "@type": "Question",
            "name": "\uAE30\uD68D\uC804\uC5D0\uC11C\uB294 \uC5B4\uB5A4 \uB178\uC2A4\uD398\uC774\uC2A4 \uD328\uB529\uC744 \uBE44\uAD50\uD560 \uC218 \uC788\uB098\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uD2B8\uB808\uC77C \uD329 \uB2E4\uC6B4 \uC7AC\uD0B7, 1996 \uB808\uD2B8\uB85C \uB215\uC2DC \uC7AC\uD0B7, \uB77C\uC774\uD2B8 \uD329 \uB2E4\uC6B4 \uC7AC\uD0B7, \uCE74\uD0C0\uB518 \uB2E4\uC6B4 \uC7AC\uD0B7\uC744 \uD655\uC778\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uB514\uC790\uC778\uACFC \uC0C9\uC0C1, \uC0AC\uC774\uC988\uB294 \uAC01 \uC0C1\uD488\uC758 \uC0C1\uC138\uD398\uC774\uC9C0\uC5D0\uC11C \uBE44\uAD50\uD574 \uC8FC\uC138\uC694."
            }
        },


        {
            "@type": "Question",
            "name": "\uAE30\uD68D\uC804\uC5D0 \uD3EC\uD568\uB41C \uBC29\uD55C\uD654\uB294 \uC5B4\uB5A4 \uC81C\uD488\uC778\uAC00\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uB215\uC2DC \uBD80\uB760 \uC20F\uACFC \uB215\uC2DC \uBBAC\uC774 \uD3EC\uD568\uB429\uB2C8\uB2E4. \uBC1C\uBAA9\uC744 \uAC10\uC2F8\uB294 \uBD80\uB760 \uD615\uD0DC\uC640 \uAC04\uD3B8\uD558\uAC8C \uC2E0\uB294 \uBBAC \uD615\uD0DC \uC911 \uC120\uD638\uD558\uB294 \uC2A4\uD0C0\uC77C\uC5D0 \uB530\uB77C \uC120\uD0DD\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4."
            }
        },


        {
            "@type": "Question",
            "name": "\uB215\uC2DC \uBD80\uB760 \uC20F\uACFC \uB215\uC2DC \uBBAC\uC740 \uBB34\uC5C7\uC774 \uB2E4\uB978\uAC00\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uB215\uC2DC \uBD80\uB760 \uC20F\uC740 \uBC1C\uBAA9\uC744 \uAC10\uC2F8\uB294 \uC20F\uBD80\uCE20 \uD615\uD0DC\uC774\uBA70, \uB215\uC2DC \uBBAC\uC740 \uB4A4\uCD95\uC774 \uC5F4\uB9B0 \uBBAC \uD615\uD0DC\uC785\uB2C8\uB2E4. \uCC29\uC6A9 \uBC29\uC2DD\uACFC \uC6D0\uD558\uB294 \uC2E4\uB8E8\uC5E3\uC744 \uAE30\uC900\uC73C\uB85C \uC120\uD0DD\uD558\uACE0, \uC18C\uC7AC\uC640 \uC0AC\uC774\uC988\uB294 \uC0C1\uD488 \uC0C1\uC138\uC815\uBCF4\uB97C \uD655\uC778\uD574 \uC8FC\uC138\uC694."
            }
        },


        {
            "@type": "Question",
            "name": "\uBC15\uBCF4\uAC80 \uCC29\uC7A5\uC5D0 \uC0AC\uC6A9\uB41C \uACA8\uC6B8 \uBAA8\uC790\uB294 \uBB34\uC5C7\uC778\uAC00\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "\uB370\uB0A0\uB9AC \uD50C\uB9AC\uC2A4 \uC774\uC5B4\uBA38\uD504 \uCEA1\uACFC TNF \uBBF8\uB4DC \uBE44\uB2C8\uAC00 \uAE30\uD68D\uC804\uC5D0 \uD3EC\uD568\uB429\uB2C8\uB2E4. \uD328\uB529\uACFC \uD568\uAED8 \uC5F0\uCD9C\uB41C \uCC29\uC7A5\uC744 \uCC38\uACE0\uD574 \uC6D0\uD558\uB294 \uB514\uC790\uC778\uC744 \uC120\uD0DD\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4."
            }
        },


        {
            "@type": "Question",
            "name": "\uD654\uBCF4 \uC18D \uCC29\uC7A5\uACFC \uBE44\uC2B7\uD558\uAC8C \uC0C1\uD488\uC744 \uC120\uD0DD\uD558\uB824\uBA74 \uC5B4\uB5BB\uAC8C \uD574\uC57C \uD558\uB098\uC694?",
            "acceptedAnswer": {
                "@type": "Answer",
